def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    sep_rows = [
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != background
    ]
    sep_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
        and grid[0][c] != background
    ]

    rb = [-1] + sep_rows + [h]
    cb = [-1] + sep_cols + [w]
    panels = [
        (rb[i] + 1, rb[i + 1], cb[j] + 1, cb[j + 1])
        for i in range(len(rb) - 1)
        for j in range(len(cb) - 1)
    ]

    def count_objects(p):
        r0, r1, c0, c1 = p
        return sum(
            grid[r][c] != background
            for r in range(r0, r1)
            for c in range(c0, c1)
        )

    source = max(panels, key=count_objects)
    r0, r1, c0, c1 = source
    pattern = [
        (r - r0, c - c0, grid[r][c])
        for r in range(r0, r1)
        for c in range(c0, c1)
        if grid[r][c] != background
    ]

    out = [row[:] for row in grid]
    for pr0, pr1, pc0, pc1 in panels:
        if (pr0, pr1, pc0, pc1) == source:
            continue
        for dr, dc, color in pattern:
            r, c = pr0 + dr, pc0 + dc
            if r < pr1 and c < pc1:
                out[r][c] = color

    return out
